import json
b = json.load(open('baseline-packages.json'))
a = json.load(open('after-cpm-packages.json'))
def pkgs(d):
    r = {}
    for p in d['projects']:
        name = p['path'].split('/')[-2]
        for f in p['frameworks']:
            for pkg in f.get('topLevelPackages', []):
                r[(name, pkg['id'])] = pkg['resolvedVersion']
    return r
bp, ap = pkgs(b), pkgs(a)
if bp == ap:
    print('All packages match baseline exactly.')
else:
    for k in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv, av = bp.get(k), ap.get(k)
        if bv != av:
            print(f'DIFF {k}: {bv} -> {av}')
"

